(() => {
'use strict';const c=window.HVT;let active=null;
const user=()=>c.currentUser?.()?.id||null;const activityQueue=new Map();
function resourceLink(id,section=null,seconds=0){const u=new URL('/',location.origin);u.searchParams.set('read',id);if(section)u.searchParams.set('section',section);if(seconds>0)u.searchParams.set('t',Math.floor(seconds));return u.href}
function record(item,completed=null,section=null,seconds=null){const actor=user();if(!actor)return Promise.resolve(null);const key=actor+':'+item.id;const previous=activityQueue.get(key)||Promise.resolve();const job=previous.catch(()=>{}).then(async()=>{if(actor!==user())throw Error('Phiên đăng nhập đã thay đổi.');const r=await c.api('/rest/v1/rpc/record_member_activity',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({p_resource_id:item.id,p_completed:completed,p_section_id:section,p_video_seconds:seconds})});return Array.isArray(r)?r[0]:r});activityQueue.set(key,job);job.then(()=>{if(activityQueue.get(key)===job)activityQueue.delete(key)},()=>{if(activityQueue.get(key)===job)activityQueue.delete(key)});return job}
async function open(item,host){close();const box=document.createElement('section');box.className='community-panel';box.innerHTML='<div class="community-tools"><a class="text-link" href="/ho-so.html">Hồ sơ & lịch sử của tôi ↗</a><button type="button" class="button secondary" data-complete>'+ (item.kind==='video'?'Đánh dấu đã xem xong':'Đánh dấu đã đọc xong')+'</button></div><p class="hint" data-activity-status></p><div class="rating-block"><p data-rating-summary>Đánh giá nội dung</p><div role="group" aria-label="Bình chọn từ một đến năm sao" class="rating-stars">'+[1,2,3,4,5].map(n=>'<button type="button" data-stars="'+n+'" aria-label="'+n+' sao" aria-pressed="false">☆</button>').join('')+'</div><p class="hint" data-rating-status></p></div><div class="share-actions"><span>Chia sẻ</span><button type="button" class="text-link" data-share="Zalo">Zalo</button><button type="button" class="text-link" data-share="Messenger">Messenger</button><a class="text-link" data-share-email>Email</a><button type="button" class="text-link" data-copy-link>Sao chép link</button></div><p class="hint" data-share-status></p><input data-share-url aria-label="Liên kết chia sẻ" readonly></section>';host.append(box);
const state={item,box,section:null,completed:false,actor:user(),video:host.querySelector('video'),busy:false,serial:0};active=state;
const valid=()=>active===state&&state.actor===user()&&box.isConnected;
const say=(selector,text)=>{if(valid())box.querySelector(selector).textContent=text};
function updateLink(){const link=resourceLink(item.id,state.section,state.video?.currentTime||0);box.querySelector('[data-share-url]').value=link;box.querySelector('[data-share-email]').href='mailto:?subject='+encodeURIComponent(item.title+' · Hiểu và Thương')+'&body='+encodeURIComponent(item.title+'\n'+link)}
function stars(value){box.querySelectorAll('[data-stars]').forEach(b=>{const n=Number(b.dataset.stars);b.textContent=n<=value?'★':'☆';b.setAttribute('aria-pressed',String(n===value))})}
async function summary(){try{const rows=await c.publicApi('/rest/v1/rpc/resource_rating_summary',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({p_resource_id:item.id})});const r=Array.isArray(rows)?rows[0]:rows;say('[data-rating-summary]',r?.total?`${r.average} / 5 · ${r.total} lượt bình chọn`:'Chưa có bình chọn. Mời bạn đánh giá từ 1–5 sao.')}catch{say('[data-rating-summary]','Chưa tải được điểm đánh giá.')}}
state.refresh=async()=>{state.actor=user();const seq=++state.serial;box.querySelector('[data-complete]').disabled=!state.actor;say('[data-activity-status]',state.actor?'Lịch sử được lưu riêng trong hồ sơ của bạn.':'Đăng nhập để lưu lịch sử và bình chọn. Bạn vẫn có thể chia sẻ nội dung.');stars(0);if(!state.actor)return;try{const rows=await c.api('/rest/v1/resource_ratings?select=stars&resource_id=eq.'+encodeURIComponent(item.id)+'&user_id=eq.'+encodeURIComponent(state.actor));if(!valid()||seq!==state.serial)return;stars(rows[0]?.stars||0);const row=await record(item);if(!valid()||seq!==state.serial)return;state.completed=!!row?.completed;box.querySelector('[data-complete]').textContent=state.completed?'Đã hoàn thành ✓ · Chuyển về đang tiếp tục':item.kind==='video'?'Đánh dấu đã xem xong':'Đánh dấu đã đọc xong';const rawTime=Number(new URLSearchParams(location.search).get('t'))||row?.video_seconds||0;const t=Number.isFinite(rawTime)?Math.max(0,Math.min(10000000,rawTime)):0;if(state.video&&t>0){const apply=()=>{if(valid())state.video.currentTime=t};if(state.video.readyState)apply();else state.video.addEventListener('loadedmetadata',apply,{once:true})}}catch{say('[data-activity-status]','Chưa lưu được lịch sử. Kiểm tra kết nối và migration V8.')}};
box.querySelector('[data-complete]').onclick=async()=>{if(!valid()||!user()||state.busy)return;state.busy=true;const b=box.querySelector('[data-complete]');b.disabled=true;try{const row=await record(item,!state.completed,state.section,state.video?.currentTime??null);if(!valid())return;state.completed=!!row.completed;b.textContent=state.completed?'Đã hoàn thành ✓ · Chuyển về đang tiếp tục':item.kind==='video'?'Đánh dấu đã xem xong':'Đánh dấu đã đọc xong';say('[data-activity-status]','Đã cập nhật trạng thái trong hồ sơ.')}catch{say('[data-activity-status]','Chưa cập nhật được. Vui lòng thử lại.')}finally{state.busy=false;if(valid())b.disabled=!user()}};
box.querySelectorAll('[data-stars]').forEach(b=>b.onclick=async()=>{const actor=user();if(!actor){say('[data-rating-status]','Đăng nhập thành viên để bình chọn.');return}if(state.ratingBusy)return;state.ratingBusy=true;try{await c.api('/rest/v1/resource_ratings?on_conflict=user_id,resource_id',{method:'POST',headers:{'Content-Type':'application/json',Prefer:'resolution=merge-duplicates'},body:JSON.stringify({user_id:actor,resource_id:item.id,stars:Number(b.dataset.stars)})});if(!valid()||actor!==user())return;stars(Number(b.dataset.stars));say('[data-rating-status]','Đã lưu '+b.dataset.stars+' sao. Bạn có thể đổi bình chọn.');await summary()}catch{say('[data-rating-status]','Chưa lưu bình chọn được. Vui lòng thử lại.')}finally{state.ratingBusy=false}});
async function copy(target=''){const link=box.querySelector('[data-share-url]').value;try{await navigator.clipboard.writeText(link);say('[data-share-status]',target?'Đã sao chép link. Mở '+target+' và dán vào cuộc trò chuyện muốn chia sẻ.':'Đã sao chép liên kết.')}catch{box.querySelector('[data-share-url]').focus();box.querySelector('[data-share-url]').select();say('[data-share-status]','Chọn và sao chép liên kết ở ô bên dưới để gửi.')}}
box.querySelector('[data-copy-link]').onclick=()=>copy();box.querySelectorAll('[data-share]').forEach(b=>b.onclick=async()=>{updateLink();if(navigator.share){try{await navigator.share({title:item.title,text:'Hiểu và Thương · '+item.title,url:box.querySelector('[data-share-url]').value});say('[data-share-status]','Chọn '+b.dataset.share+' trong bảng chia sẻ của thiết bị nếu có.')}catch(e){if(e.name!=='AbortError')await copy(b.dataset.share)}}else await copy(b.dataset.share)});
if(state.video){let last=0;state.video.addEventListener('timeupdate',()=>{updateLink();if(valid()&&user()&&Date.now()-last>10000){last=Date.now();record(item,null,state.section,state.video.currentTime).catch(()=>{})}});state.video.addEventListener('ended',()=>{if(valid()&&user())record(item,true,state.section,state.video.currentTime).then(()=>state.refresh()).catch(()=>{})})}
updateLink();state.updateLink=updateLink;summary();state.refresh();
}
function close(){if(active?.video&&active.actor===user()&&user())record(active.item,null,active.section,active.video.currentTime).catch(()=>{});active=null}
window.HVTCommunity={open,close,resourceLink,record,section(id){if(active){active.section=id;active.updateLink();if(user())record(active.item,null,id).catch(()=>{})}}};
for(const event of ['hvt-auth-change','hvt-auth-lost'])window.addEventListener(event,()=>active?.refresh());
})();
